<style>
.gt-modal-xl{max-width:1180px;width:min(1180px,calc(100vw - 28px))}.gt-task-modal-layout{display:grid;grid-template-columns:minmax(0,1fr)340px;gap:18px;background:#f8fafc}.gt-task-modal-main,.gt-task-modal-sidebar{min-width:0}.gt-task-modal-sidebar{display:flex;flex-direction:column;gap:12px}.gt-input-lg{min-height:48px;font-size:15px}.gt-textarea-lg{min-height:132px}.gt-sidebar-card{background:#fff;border:1px solid var(--gt-border);border-radius:16px;box-shadow:var(--gt-shadow-sm);padding:13px}.gt-sidebar-card-title{font-weight:950;color:#111827;margin-bottom:10px}.gt-sidebar-toggle{width:100%;border:0;background:transparent;display:flex;align-items:center;justify-content:space-between;gap:10px;font-weight:950;color:#111827;padding:0;cursor:pointer}.gt-sidebar-toggle span{display:inline-flex;align-items:center;gap:8px}.gt-sidebar-toggle-body{padding-top:12px}.gt-switch-line{display:flex;align-items:flex-start;gap:9px;border:1px solid var(--gt-border);background:#fff;border-radius:12px;padding:10px;font-size:13px;font-weight:800}.gt-switch-line input{margin-top:2px;accent-color:var(--gt-primary)}.gt-step-builder{display:none}.gt-step-builder.active{display:block}.gt-step-row{background:#fff;border:1px solid var(--gt-border);border-radius:18px;margin-bottom:12px;overflow:hidden;box-shadow:var(--gt-shadow-sm)}.gt-step-row-head{width:100%;border:0;background:linear-gradient(135deg,#ffffff 0%,#f4fae7 100%);display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 16px;text-align:left;cursor:pointer}.gt-step-row-title{display:block;font-size:11px;font-weight:950;color:#4d7c0f;text-transform:uppercase;letter-spacing:.06em;margin-bottom:4px}.gt-step-row-head strong{font-size:14px;color:#111827}.gt-step-row-actions{display:inline-flex;align-items:center;gap:8px}.gt-step-row.collapsed .gt-step-row-body{display:none}.gt-step-row.collapsed .gt-step-row-actions svg{transform:rotate(-90deg)}.gt-step-row-body{padding:16px}.gt-step-grid{display:grid;grid-